% assign_conductivity.m — Map a 2-D conductivity grid onto EIDORS mesh elements.
%
% The conductivity grid is generated by the Python src/data_representations layer
% and passed in as a text file. Each FEM element's centroid is mapped to the
% nearest grid pixel using bilinear/nearest-neighbour interpolation.
%
% Usage:
%   img_out = assign_conductivity(img, grid_path, x_min, x_max, y_min, y_max, fallback_cond)
%
% Inputs:
%   img           — EIDORS image with fwd_model set (nodes/elems in [-1,1] space)
%   grid_path     — path to whitespace-delimited text file holding the grid (rows × cols)
%   x_min, x_max  — physical x extent of the grid (metres)
%   y_min, y_max  — physical y extent of the grid (metres)
%   fallback_cond — conductivity (S/m) used for elements whose centroid falls
%                   outside the grid (e.g. base/background conductivity)
%
% Outputs:
%   img_out — EIDORS image with elem_data assigned from the grid

function img_out = assign_conductivity(img, grid_path, x_min, x_max, y_min, y_max, fallback_cond)
    if nargin < 7
        fallback_cond = 1.0;
    end

    % Load the conductivity grid produced by Python
    grid_vals = load(grid_path);   % size: [ny, nx]
    [ny, nx]  = size(grid_vals);

    % Build the physical coordinate axes matching the Python linspace
    x_axis = linspace(x_min, x_max, nx);
    y_axis = linspace(y_min, y_max, ny);
    [X, Y] = meshgrid(x_axis, y_axis);

    % Compute element centroids in physical coordinates (EIDORS mesh lives in [-1,1])
    nodes = img.fwd_model.nodes;
    elems = img.fwd_model.elems;
    cx = (nodes(elems(:,1), 1) + nodes(elems(:,2), 1) + nodes(elems(:,3), 1)) / 3.0;
    cy = (nodes(elems(:,1), 2) + nodes(elems(:,2), 2) + nodes(elems(:,3), 2)) / 3.0;

    % Scale EIDORS unit-disk centroids to physical domain
    r_x = (x_max - x_min) / 2.0;
    r_y = (y_max - y_min) / 2.0;
    cx_phys = cx * r_x + (x_max + x_min) / 2.0;
    cy_phys = cy * r_y + (y_max + y_min) / 2.0;

    % Nearest-neighbour lookup — avoids smoothing artefacts at sharp boundaries
    elem_cond = interp2(X, Y, grid_vals, cx_phys, cy_phys, 'nearest');

    % Fill any centroids that landed outside the grid with the fallback
    elem_cond(isnan(elem_cond)) = fallback_cond;

    img_out          = img;
    img_out.elem_data = elem_cond;
end
